mapper.select:
SELECT COALESCE(SUM(CASE WHEN co.state = 1 THEN co.amount ELSE 0 END), 0) as chargeOrderAmount, COUNT(*) as charge_order_cnt FROM tb_charge_order co LEFT JOIN tb_user u ON co.user_id = u.id
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
AND co.create_time >= FROM_UNIXTIME(#{startTime}/1000)
AND co.create_time <= FROM_UNIXTIME(#{endTime}/1000)

SELECT COALESCE(SUM(CASE WHEN wo.state = 2 THEN wo.amount ELSE 0 END), 0) as withdrawOrderAmount, COUNT(*) as withdraw_order_cnt FROM tb_withdraw_order wo LEFT JOIN tb_user u ON wo.user_id = u.id
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
AND wo.create_time >= FROM_UNIXTIME(#{startTime}/1000)
AND wo.create_time <= FROM_UNIXTIME(#{endTime}/1000)

SELECT 
    COUNT(CASE WHEN p.status = 1 THEN 1 END) as online_privilege_cnt,
    (SELECT COUNT(*) FROM tb_investment_record ir
     LEFT JOIN tb_user u ON ir.user_id = u.id





                 AND u.agent = #{currentUserId}



                 AND u.salesmanid = #{currentUserId}





             AND ir.order_date >= FROM_UNIXTIME(#{startTime}/1000)


             AND ir.order_date <= FROM_UNIXTIME(#{endTime}/1000)


    ) as privilege_cnt
FROM tb_project p

SELECT COUNT(*) as zc_cnt FROM tb_user u
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
AND u.create_date >= FROM_UNIXTIME(#{startTime}/1000)
AND u.create_date <= FROM_UNIXTIME(#{endTime}/1000)

SELECT COALESCE(SUM(ir.investment_amount), 0) AS xs_amount FROM tb_investment_record ir LEFT JOIN tb_user u ON ir.user_id = u.id
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
AND ir.order_date >= FROM_UNIXTIME(#{startTime}/1000)
AND ir.order_date <= FROM_UNIXTIME(#{endTime}/1000)

SELECT DATE_FORMAT(date_column, '%Y-%m-%d') as date, COALESCE(SUM(CASE WHEN source = 'charge' THEN amount ELSE 0 END), 0) as totalCharges, COALESCE(SUM(CASE WHEN source = 'withdraw' THEN amount ELSE 0 END), 0) as totalWithdraws, COALESCE(SUM(CASE WHEN source = 'investment' THEN amount ELSE 0 END), 0) as totalOrders FROM ( SELECT co.create_time as date_column, 'charge' as source, CASE WHEN co.state = 1 THEN co.amount ELSE 0 END as amount FROM tb_charge_order co LEFT JOIN tb_user u ON co.user_id = u.id
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
AND co.create_time >= FROM_UNIXTIME(#{startTime}/1000)
AND co.create_time <= FROM_UNIXTIME(#{endTime}/1000)
UNION ALL
SELECT wo.create_time as date_column, 'withdraw' as source, CASE WHEN wo.state = 1 THEN wo.amount ELSE 0 END as amount FROM tb_withdraw_order wo LEFT JOIN tb_user u ON wo.user_id = u.id
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
AND wo.create_time >= FROM_UNIXTIME(#{startTime}/1000)
AND wo.create_time <= FROM_UNIXTIME(#{endTime}/1000)
UNION ALL
SELECT ir.order_date as date_column, 'investment' as source, ir.investment_amount as amount FROM tb_investment_record ir LEFT JOIN tb_user u ON ir.user_id = u.id
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
AND ir.order_date >= FROM_UNIXTIME(#{startTime}/1000)
AND ir.order_date <= FROM_UNIXTIME(#{endTime}/1000)
) combined_data GROUP BY DATE_FORMAT(date_column, '%Y-%m-%d') ORDER BY date
